    config: &BivvyConfig,
    visited: &mut HashSet<String>,
    depth: usize,
) -> Result<BivvyConfig> {
    if depth > self.max_depth {
        return Err(anyhow!(
            "Config extends depth exceeds maximum of {}",
            self.max_depth
        ));
    }

